UPDATE products SET description='«Бамбино» — компактная форма алоказии из группы Alocasia × amazonica. Её узкие стреловидные листья с контрастными жилками образуют плотный куст. Растению нужны тепло, рассеянный свет и рыхлый грунт без застоя воды; листья и сок не следует пробовать на вкус.',updated_at=CURRENT_TIMESTAMP WHERE product_code=19 AND name='Алоказия Бамбино' AND catalog_section='plants' AND status='published' AND md5(COALESCE(description,''))='0be73a5bc3684d1d6dcf94c3763564e0';
