UPDATE products SET description='Антуриум Варока — декоративнолистный вид с длинными бархатистыми листьями и заметными светлыми жилками. Взрослые листья могут свисать ниже края горшка. Растение ценят за листву; ему нужны тепло, высокая влажность и рыхлый субстрат для ароидных.',updated_at=CURRENT_TIMESTAMP WHERE product_code=35 AND name='Антуриум варок' AND catalog_section='plants' AND status='published' AND md5(COALESCE(description,''))='06a9494c96198ea27711125f156230eb';
