UPDATE products SET description='«Regal Shields» — крупный гибрид алоказии, выращиваемый ради выразительных сердцевидных листьев. Верхняя сторона листа тёмно-зелёная со светлыми жилками, нижняя — бордовая. В подходящих условиях растение со временем заметно увеличивается, поэтому ему нужны место, устойчивый горшок и яркий рассеянный свет.',updated_at=CURRENT_TIMESTAMP WHERE product_code=483 AND name='Алоказия Регал Шилд' AND catalog_section='plants' AND status='published' AND md5(COALESCE(description,''))='b3ea2b00d1cb6bbf13d1fac1daff3e96';
