UPDATE products SET description='Антуриум Вейча выращивают прежде всего ради длинных рельефных листьев с выраженными продольными жилками. По мере взросления листья становятся крупнее. Неброское соцветие может появиться у взрослого растения, но главная декоративная особенность вида — листва. Нужны тепло, высокая влажность и яркий рассеянный свет.',updated_at=CURRENT_TIMESTAMP WHERE product_code=532 AND name='Антуриум Вейча' AND catalog_section='plants' AND status='published' AND md5(COALESCE(description,''))='1f2cc4f9f9b385cd47110b923232af0e';
