UPDATE products SET description='«Queen of Hearts» ценят за крупные сердцевидные листья с плотной фактурой. Молодые листья могут иметь красноватый или бронзовый оттенок и затем темнеют. Это декоративнолистный антуриум: его покупают ради листвы, а не ярких цветочных покрывал. Для роста нужны тепло, рассеянный свет и рыхлый воздухопроницаемый субстрат.',updated_at=CURRENT_TIMESTAMP WHERE product_code=644 AND name='Антуриум Квин оф Хертс' AND catalog_section='plants' AND status='published' AND md5(COALESCE(description,''))='1acf32ad94b3651a0c90f50646c0e3c4';
